const item = $input.first();
const body = (item.json && item.json.body) ? item.json.body : (item.json || {});
const binary = item.binary || {};
const keys = Object.keys(binary);
let resume_base64 = '';
let filename = '';
if (keys.length > 0) {
  // The webhook names the binary property after the form field (or by the
  // node option); take whatever arrived - there is only one file here.
  const key = keys[0];
  const buffer = await this.helpers.getBinaryDataBuffer(0, key);
  resume_base64 = buffer.toString('base64');
  filename = (binary[key] && binary[key].fileName) || key;
}
return [{
  json: {
    resume_base64,
    filename: filename || 'resume',
    jd_text: typeof body.jd_text === 'string' ? body.jd_text : '',
    job_url: typeof body.job_url === 'string' ? body.job_url : '',
  },
}];

const screening = $('Screen resume').first().json.body || {};
const raw = String(($json && $json.output) || '').trim();
const fields = { skills: '', experience: '', missing: '', verdict: '' };
// Strip markdown bold and leading bullets/dashes so label lines still match.
const norm = raw.replace(/\*\*/g, '').replace(/^[*\u2022\-\s]+/gm, '').trim();
// Models wrap label values across lines; split on the label markers instead of
// scanning line-by-line, so 'Skills:\nFirst sentence.\nSecond…' keeps its text.
const parts = norm.split(/^\s*(Skills|Experience|Missing|Verdict)\s*:\s*/mi);
if (parts.length > 1) {
  for (let i = 1; i < parts.length; i += 2) {
    if (i + 1 < parts.length) fields[parts[i].toLowerCase()] = (parts[i + 1] || '').trim();
  }
}
// A model that ignores the four-label contract still gets a usable answer.
if (!fields.verdict) fields.verdict = raw;
return [{
  json: {
    ok: true,
    ats: screening.ats,
    jd_origin: screening.jd_origin,
    jd_chars: screening.jd_chars,
    resume_chars: screening.resume_chars,
    ocr: screening.ocr,
    analysis: fields,
    note: 'ats.total was computed by JobScope ats_score.score_resume; the AI Agent only explains it.',
  },
}];

const res = $json || {};
const body = res.body || res;
const detail = body.detail
  || (res.error && (res.error.message || res.error))
  || 'screening failed';
return [{
  json: {
    ok: false,
    error: typeof detail === 'string' ? detail : JSON.stringify(detail),
    status: Number(res.statusCode) || 502,
  },
}];
